Here's a single-file game called **Orb Runner**. Collect glowing orbs (gold ones are worth 3) and dodge the red shards. From level 3, purple seeker shards start chasing you. Reach 50 points to win.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Orb Runner</title>
<style>
  html, body {
    margin: 0; height: 100%; overflow: hidden;
    background: #05060f; font-family: system-ui, sans-serif;
  }
  canvas {
    display: block; width: 100vw; height: 100vh;
    cursor: crosshair; touch-action: none; user-select: none;
  }
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
(() => {
'use strict';

// ---------- Setup ----------
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
let W = 0, H = 0, DPR = 1;

function resize() {
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  W = window.innerWidth;
  H = window.innerHeight;
  canvas.width = Math.floor(W * DPR);
  canvas.height = Math.floor(H * DPR);
}
window.addEventListener('resize', resize);
resize();

const WIN_SCORE = 50;
const PLAYER_R = 14;
const ORB_R = 9;
const PLAYER_SPEED = 330;

const MOVE = {
  arrowup: [0, -1], w: [0, -1],
  arrowdown: [0, 1], s: [0, 1],
  arrowleft: [-1, 0], a: [-1, 0],
  arrowright: [1, 0], d: [1, 0]
};

// ---------- State ----------
const game = { state: 'menu', score: 0, time: 0, level: 1, paused: false };
window.gameState = { score: 0, state: 'menu' };
function syncState() {
  window.gameState.score = game.score;
  window.gameState.state = game.state;
}

let best = 0;
let endedAt = 0;
let banner = null;
let shake = 0;
let player = { x: 0, y: 0 };
let orbs = [], hazards = [], particles = [];
let orbTimer = 0, hazardTimer = 0;
const keys = {};
const pointer = { x: 0, y: 0, active: false };

const stars = Array.from({ length: 90 }, () => ({
  fx: Math.random(), fy: Math.random(),
  sp: 0.2 + Math.random() * 0.8, r: 0.5 + Math.random() * 1.3
}));

// ---------- Audio (generated in code) ----------
let actx = null, master = null, noiseBuf = null;
function ensureAudio() {
  try {
    if (!actx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      actx = new AC();
      master = actx.createGain();
      master.gain.value = 0.3;
      master.connect(actx.destination);
      const len = Math.floor(actx.sampleRate * 0.6);
      noiseBuf = actx.createBuffer(1, len, actx.sampleRate);
      const d = noiseBuf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    }
    if (actx.state === 'suspended') actx.resume();
  } catch (e) {
    actx = null;
  }
}
function tone(freq, dur, type = 'sine', vol = 0.25, slideTo = 0, delay = 0) {
  if (!actx) return;
  const t0 = actx.currentTime + delay;
  const o = actx.createOscillator();
  const g = actx.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, t0);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(vol, t0 + 0.015);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  o.connect(g); g.connect(master);
  o.start(t0); o.stop(t0 + dur + 0.05);
}
function noise(vol = 0.4) {
  if (!actx || !noiseBuf) return;
  const s = actx.createBufferSource();
  s.buffer = noiseBuf;
  const g = actx.createGain();
  g.gain.value = vol;
  s.connect(g); g.connect(master);
  s.start();
}
const sfx = {
  start()     { tone(440, 0.1, 'square', 0.12, 880); tone(660, 0.14, 'square', 0.12, 990, 0.09); },
  collect(g)  { tone(g ? 990 : 760, 0.12, 'triangle', 0.3, g ? 1560 : 1140); },
  level()     { [523, 659, 784, 1046].forEach((f, i) => tone(f, 0.16, 'triangle', 0.25, 0, i * 0.08)); },
  hit()       { tone(260, 0.7, 'sawtooth', 0.3, 35); noise(0.35); },
  win()       { [523, 659, 784, 1046, 1318].forEach((f, i) => tone(f, 0.3, 'triangle', 0.28, 0, i * 0.1)); }
};

// ---------- Input ----------
window.addEventListener('keydown', e => {
  const k = e.key.toLowerCase();
  if (MOVE[k]) {
    keys[k] = true;
    pointer.active = false;
    e.preventDefault();
    return;
  }
  if (k === 'enter' || k === ' ') {
    e.preventDefault();
    if (!e.repeat) action();
    return;
  }
  if (k === 'p' || k === 'escape') {
    e.preventDefault();
    if (!e.repeat && game.state === 'playing') game.paused = !game.paused;
  }
});
window.addEventListener('keyup', e => {
  delete keys[e.key.toLowerCase()];
});
window.addEventListener('blur', () => {
  for (const k in keys) delete keys[k];
});
canvas.addEventListener('pointermove', e => {
  pointer.x = e.clientX; pointer.y = e.clientY; pointer.active = true;
});
canvas.addEventListener('pointerdown', e => {
  pointer.x = e.clientX; pointer.y = e.clientY; pointer.active = true;
  action();
});
canvas.addEventListener('pointerleave', () => { pointer.active = false; });

function action() {
  ensureAudio();
  if (game.state === 'menu') {
    startGame();
  } else if ((game.state === 'over' || game.state === 'won') && performance.now() - endedAt > 700) {
    startGame();
  }
}

// ---------- Game logic ----------
function fmt(t) {
  const s = Math.floor(t);
  return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
}

function burst(x, y, col, power) {
  for (let i = 0; i < 14; i++) {
    const a = Math.random() * Math.PI * 2;
    const s = (80 + Math.random() * 220) * power;
    const life = 0.5 + Math.random() * 0.4;
    particles.push({
      x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s,
      life, max: life, s: 2 + Math.random() * 2.5, col
    });
  }
}

function spawnOrb() {
  let x, y, tries = 0;
  do {
    x = 24 + Math.random() * Math.max(1, W - 48);
    y = 24 + Math.random() * Math.max(1, H - 48);
    tries++;
  } while (Math.hypot(x - player.x, y - player.y) < 120 && tries < 20);
  const golden = Math.random() < 0.12;
  orbs.push({ x, y, ph: Math.random() * 6.28, golden, r: golden ? 11 : ORB_R });
}

function spawnHazard(initial) {
  const base = Math.min(340, 110 + game.time * 2.2);
  const seekChance = game.level >= 3 ? Math.min(0.4, 0.15 + (game.level - 3) * 0.05) : 0;
  const seek = Math.random() < seekChance;
  const speed = seek ? base * 0.7 : base * (0.8 + Math.random() * 0.4);
  let x, y, a;
  if (initial) {
    let tries = 0;
    do {
      x = Math.random() * W;
      y = Math.random() * H;
      tries++;
    } while (Math.hypot(x - player.x, y - player.y) < 180 && tries < 30);
    a = Math.random() * Math.PI * 2;
  } else {
    const side = Math.floor(Math.random() * 4);
    if (side === 0)      { x = Math.random() * W; y = -30; }
    else if (side === 1) { x = W + 30; y = Math.random() * H; }
    else if (side === 2) { x = Math.random() * W; y = H + 30; }
    else                 { x = -30; y = Math.random() * H; }
    const tx = W * (0.2 + Math.random() * 0.6);
    const ty = H * (0.2 + Math.random() * 0.6);
    a = Math.atan2(ty - y, tx - x);
  }
  hazards.push({
    x, y,
    vx: Math.cos(a) * speed, vy: Math.sin(a) * speed, speed,
    r: 11 + Math.random() * 9,
    seek,
    spin: (Math.random() - 0.5) * 3,
    rot: Math.random() * 6.28,
    life: 0
  });
}

function resetWorld() {
  player = { x: W / 2, y: H / 2 };
  orbs = []; hazards = []; particles = [];
  game.score = 0; game.time = 0; game.level = 1; game.paused = false;
  orbTimer = 0; hazardTimer = 1.5;
  for (let i = 0; i < 4; i++) spawnOrb();
  for (let i = 0; i < 3; i++) spawnHazard(true);
}

function startGame() {
  ensureAudio();
  resetWorld();
  game.state = 'playing';
  banner = { text: 'GO!', t: 0 };
  sfx.start();
  syncState();
}

function endGame(won) {
  game.state = won ? 'won' : 'over';
  best = Math.max(best, game.score);
  endedAt = performance.now();
  if (won) {
    sfx.win();
    burst(player.x, player.y, '255,210,80', 1.2);
  } else {
    sfx.hit();
    shake = 1;
    burst(player.x, player.y, '255,61,90', 1.2);
  }
  syncState();
}

function update(dt) {
  game.time += dt;

  // Level progression (every 20 seconds)
  const lvl = Math.floor(game.time / 20) + 1;
  if (lvl !== game.level) {
    game.level = lvl;
    banner = { text: 'LEVEL ' + lvl, t: 0 };
    sfx.level();
  }

  // Player movement: keyboard overrides; otherwise follow the pointer
  let mx = 0, my = 0;
  for (const k in keys) {
    const m = MOVE[k];
    if (m) { mx += m[0]; my += m[1]; }
  }
  let moving = false;
  if (mx || my) {
    const l = Math.hypot(mx, my);
    player.x += mx / l * PLAYER_SPEED * dt;
    player.y += my / l * PLAYER_SPEED * dt;
    moving = true;
  } else if (pointer.active) {
    const dx = pointer.x - player.x, dy = pointer.y - player.y;
    const d = Math.hypot(dx, dy);
    if (d > 0.5) {
      const step = Math.min(d, PLAYER_SPEED * 1.6 * dt);
      player.x += dx / d * step;
      player.y += dy / d * step;
      moving = true;
    }
  }
  player.x = Math.max(PLAYER_R, Math.min(W - PLAYER_R, player.x));
  player.y = Math.max(PLAYER_R, Math.min(H - PLAYER_R, player.y));

  if (moving && Math.random() < 0.6) {
    particles.push({
      x: player.x + (Math.random() - 0.5) * 6,
      y: player.y + (Math.random() - 0.5) * 6,
      vx: 0, vy: 0, life: 0.35, max: 0.35, s: 3, col: '90,240,255'
    });
  }

  // Spawning (difficulty ramps with time)
  orbTimer -= dt;
  if (orbTimer <= 0) {
    if (orbs.length < 7) spawnOrb();
    orbTimer = 0.9 + Math.random() * 0.7;
  }
  const maxHazards = Math.min(40, 4 + Math.floor(game.time / 12));
  const hazardInterval = Math.max(0.35, 1.6 - game.time * 0.012);
  hazardTimer -= dt;
  if (hazardTimer <= 0) {
    if (hazards.length < maxHazards) spawnHazard(false);
    hazardTimer = hazardInterval * (0.7 + Math.random() * 0.6);
  }

  // Hazard movement
  for (const h of hazards) {
    h.life += dt;
    h.rot += h.spin * dt;
    if (h.seek) {
      const dx = player.x - h.x, dy = player.y - h.y;
      const d = Math.hypot(dx, dy) || 1;
      const turn = Math.min(1, 1.6 * dt);
      h.vx += (dx / d * h.speed - h.vx) * turn;
      h.vy += (dy / d * h.speed - h.vy) * turn;
      const m = Math.hypot(h.vx, h.vy) || 1;
      h.vx = h.vx / m * h.speed;
      h.vy = h.vy / m * h.speed;
    }
    h.x += h.vx * dt;
    h.y += h.vy * dt;
  }
  hazards = hazards.filter(h =>
    h.x > -120 && h.x < W + 120 && h.y > -120 && h.y < H + 120 &&
    !(h.seek && h.life > 12)
  );

  // Hazard collisions
  for (const h of hazards) {
    if (Math.hypot(h.x - player.x, h.y - player.y) < h.r * 0.75 + PLAYER_R * 0.7) {
      endGame(false);
      return;
    }
  }

  // Orb collection
  const kept = [];
  for (const o of orbs) {
    if (Math.hypot(o.x - player.x, o.y - player.y) < PLAYER_R + o.r + 4) {
      game.score += o.golden ? 3 : 1;
      burst(o.x, o.y, o.golden ? '255,210,80' : '90,255,220', 0.6);
      sfx.collect(o.golden);
    } else {
      kept.push(o);
    }
  }
  orbs = kept;

  if (game.score >= WIN_SCORE) {
    endGame(true);
  }
}

function stepParticles(dt) {
  for (const p of particles) {
    p.life -= dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.vx *= 0.96;
    p.vy *= 0.96;
  }
  particles = particles.filter(p => p.life > 0);
}

// ---------- Rendering ----------
function text(str, x, y, size, color, weight = '700', align = 'center') {
  ctx.font = `${weight} ${size}px system-ui, sans-serif`;
  ctx.fillStyle = color;
  ctx.textAlign = align;
  ctx.textBaseline = 'middle';
  ctx.fillText(str, x, y);
}

function dim(alpha) {
  ctx.fillStyle = `rgba(3,4,12,${alpha})`;
  ctx.fillRect(0, 0, W, H);
}

function drawBackground(now) {
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#0a0b22');
  g.addColorStop(1, '#020208');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = '#ffffff';
  for (const s of stars) {
    const x = ((s.fx * W - now * 0.01 * s.sp) % W + W) % W;
    const y = s.fy * H;
    ctx.globalAlpha = 0.25 + 0.35 * s.sp;
    ctx.beginPath();
    ctx.arc(x, y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawOrb(o, now) {
  const pulse = 1 + Math.sin(now * 0.005 + o.ph) * 0.15;
  const r = o.r * pulse;
  const col = o.golden ? '255,210,80' : '90,255,220';
  const g = ctx.createRadialGradient(o.x, o.y, 0, o.x, o.y, r * 3.2);
  g.addColorStop(0, `rgba(${col},0.9)`);
  g.addColorStop(0.3, `rgba(${col},0.35)`);
  g.addColorStop(1, `rgba(${col},0)`);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(o.x, o.y, r * 3.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(o.x, o.y, r * 0.55, 0, Math.PI * 2);
  ctx.fill();
}

function drawHazard(h) {
  ctx.save();
  ctx.translate(h.x, h.y);
  ctx.rotate(h.rot);
  const col = h.seek ? '#b15cff' : '#ff3d5a';
  ctx.shadowColor = col;
  ctx.shadowBlur = 14;
  ctx.fillStyle = col;
  ctx.beginPath();
  for (let i = 0; i < 12; i++) {
    const a = i / 12 * Math.PI * 2;
    const rr = (i % 2) ? h.r * 0.55 : h.r;
    const px = Math.cos(a) * rr, py = Math.sin(a) * rr;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
  ctx.shadowBlur = 0;
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.beginPath();
  ctx.arc(0, 0, h.r * 0.25, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawPlayer(now) {
  if (game.state !== 'playing' && game.state !== 'won') return;
  const r = PLAYER_R;
  const g = ctx.createRadialGradient(player.x, player.y, r * 0.5, player.x, player.y, r * 3);
  g.addColorStop(0, 'rgba(120,255,240,0.6)');
  g.addColorStop(1, 'rgba(120,255,240,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(player.x, player.y, r * 3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#f2fffd';
  ctx.beginPath();
  ctx.arc(player.x, player.y, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#5ff7dc';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(player.x, player.y, r + 4 + Math.sin(now * 0.008) * 1.5, 0, Math.PI * 2);
  ctx.stroke();
}

function drawParticles() {
  for (const p of particles) {
    ctx.globalAlpha = Math.max(0, p.life / p.max);
    ctx.fillStyle = `rgb(${p.col})`;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.s, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawHUD() {
  text(`SCORE ${game.score} / ${WIN_SCORE}`, 20, 24, 22, '#ffffff', '700', 'left');
  ctx.fillStyle = 'rgba(255,255,255,0.15)';
  ctx.fillRect(20, 42, 220, 6);
  ctx.fillStyle = '#5ff7dc';
  ctx.fillRect(20, 42, 220 * Math.min(1, game.score / WIN_SCORE), 6);
  text(`LEVEL ${game.level}`, 20, 66, 16, '#b9c7e0', '600', 'left');
  text(`TIME ${fmt(game.time)}`, 20, 88, 16, '#b9c7e0', '600', 'left');
  text(`BEST ${best}`, W - 20, 24, 16, '#b9c7e0', '600', 'right');
}

function drawBanner() {
  if (!banner || game.state !== 'playing') return;
  const a = Math.max(0, Math.min(1, (1.4 - banner.t) * 2));
  const sc = 1 + Math.max(0, 0.3 - banner.t) * 0.5;
  ctx.save();
  ctx.globalAlpha = a;
  ctx.translate(W / 2, H * 0.35);
  ctx.scale(sc, sc);
  ctx.shadowColor = '#5ff7dc';
  ctx.shadowBlur = 25;
  text(banner.text, 0, 0, 56, '#eafffb', '800');
  ctx.restore();
}

function drawMenu(now) {
  dim(0.35);
  const cx = W / 2;
  ctx.save();
  ctx.shadowColor = '#5ff7dc';
  ctx.shadowBlur = 30;
  text('ORB RUNNER', cx, H * 0.17, Math.min(84, W / 9), '#eafffb', '800');
  ctx.restore();
  text('Collect the glowing orbs. Dodge the shards. It only gets faster.',
       cx, H * 0.17 + 60, 18, '#b9c7e0', '400');

  const lines = [
    ['Move', 'Arrow keys / WASD'],
    ['Steer with mouse', 'Move the pointer over the arena'],
    ['Pause', 'P or Esc'],
    ['Start / Retry', 'Enter, Space or click'],
    ['Goal', 'Collect 50 points (gold orb = 3)']
  ];
  const pw = Math.min(560, W - 40);
  const ph = lines.length * 34 + 30;
  const px = cx - pw / 2;
  const py = H * 0.34;
  ctx.fillStyle = 'rgba(15,18,40,0.8)';
  ctx.strokeStyle = 'rgba(95,247,220,0.4)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.roundRect(px, py, pw, ph, 14);
  ctx.fill();
  ctx.stroke();
  lines.forEach(([label, value], i) => {
    const y = py + 30 + i * 34;
    text(label, px + 24, y, 17, '#7fe9ff', '700', 'left');
    text(value, px + pw - 24, y, 17, '#ffffff', '400', 'right');
  });

  const blink = 0.5 + 0.5 * Math.sin(now * 0.006);
  ctx.globalAlpha = 0.4 + 0.6 * blink;
  text('Press ENTER, SPACE or CLICK to start', cx, H * 0.8, 24, '#ffffff', '700');
  ctx.globalAlpha = 1;
}

function drawEndScreen(now, won) {
  dim(0.6);
  const cx = W / 2, cy = H / 2;
  ctx.save();
  ctx.shadowColor = won ? '#ffd250' : '#ff4d6d';
  ctx.shadowBlur = 30;
  text(won ? 'YOU WIN!' : 'GAME OVER', cx, cy - 80, 64, won ? '#ffe08a' : '#ff6b84', '800');
  ctx.restore();
  if (won) {
    text(`You collected ${game.score} points in ${fmt(game.time)}.`, cx, cy - 10, 24, '#ffffff');
  } else {
    text(`Score ${game.score}`, cx, cy - 10, 26, '#ffffff');
    text(`Survived ${fmt(game.time)}  |  Level ${game.level}`, cx, cy + 28, 18, '#b9c7e0', '400');
  }
  text(`Best ${best}`, cx, cy + 62, 18, '#7fe9ff', '600');
  if (performance.now() - endedAt > 700) {
    const blink = 0.5 + 0.5 * Math.sin(now * 0.006);
    ctx.globalAlpha = 0.4 + 0.6 * blink;
    text('Press ENTER, SPACE or CLICK to play again', cx, cy + 120, 22, '#ffffff', '700');
    ctx.globalAlpha = 1;
  }
}

function drawPaused() {
  dim(0.5);
  text('PAUSED', W / 2, H / 2 - 20, 56, '#ffffff', '800');
  text('Press P or Esc to resume', W / 2, H / 2 + 30, 20, '#b9c7e0', '400');
}

function render(now) {
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  ctx.save();
  if (shake > 0) {
    ctx.translate((Math.random() - 0.5) * shake * 16, (Math.random() - 0.5) * shake * 16);
  }
  drawBackground(now);

  if (game.state !== 'menu') {
    for (const o of orbs) drawOrb(o, now);
    for (const h of hazards) drawHazard(h);
    drawParticles();
    drawPlayer(now);
    drawHUD();
    drawBanner();
  }

  if (game.state === 'menu') {
    drawMenu(now);
  } else if (game.state === 'over' || game.state === 'won') {
    drawEndScreen(now, game.state === 'won');
  } else if (game.paused) {
    drawPaused();
  }

  ctx.restore();
}

// ---------- Main loop ----------
let last = performance.now();
function frame(now) {
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;

  if (game.state === 'playing' && !game.paused) update(dt);
  stepParticles(dt);
  if (banner) {
    banner.t += dt;
    if (banner.t > 1.4) banner = null;
  }
  if (shake > 0) shake = Math.max(0, shake - dt * 2.5);

  render(now);
  syncState();
  requestAnimationFrame(frame);
}

syncState();
requestAnimationFrame(frame);
})();
</script>
</body>
</html>
